  ('maslo-dlya-gub-crystal-prozrachnyiy-100780', '透明唇油', '彩妆', (SELECT id FROM product_categories WHERE name = '彩妆' LIMIT 1), '透明色调可增强双唇的自然美感，质感每日呵护双唇。

